typedef unsigned int size_t;

void *operator new(size_t, unsigned int, const char *, int);

class MenuEntry
{
public:
	int type;
	virtual ~MenuEntry();
};

class MenuEntryTitle : public MenuEntry
{
	const char *text;

public:
	MenuEntryTitle(const char *t) : text(t)
	{
		type = 3;
		Disable();
	}
	void Disable();
};

class MenuEntryIntEdit : public MenuEntry
{
public:
	MenuEntryIntEdit(const char *, int *, int, int);
};

class MenuSystem;

class Menu
{
public:
	void ClearMenu();
	void AddEntry(MenuEntry *);
	virtual void OnOpen(Menu *, MenuSystem *);
};

class MenuSystem
{
public:
	void Refresh();
};

class stringx
{
	const char *text;
	char pad[4];

public:
	const char *c_str() const { return text; }
};

enum { TRICK_NUM = 95 };

struct SurferTrick
{
	int Points;
	char pad[84];
};

extern SurferTrick GTrickList[];
extern const stringx ksGlobalTrickTextArray[];

bool mem_malloc_locked();
void mem_lock_malloc(bool);

class TrickMenu : public Menu
{
public:
	virtual void OnOpen(Menu *, MenuSystem *);
};

void TrickMenu::OnOpen(Menu *cto, MenuSystem *c)
{
	bool				memlocked = mem_malloc_locked();
	MenuEntryIntEdit *	pmeie;

	// Trick menu externs.
	extern struct SurferTrick GTrickList[];

	mem_lock_malloc(false);

	ClearMenu();

	AddEntry(new(0, "KS/SRC/ks/menu_scoring.cpp", 0) MenuEntryTitle("Trick Menu"));

	for (int i = 0; i < TRICK_NUM; i++)
	{
		pmeie = new(0, "KS/SRC/ks/menu_scoring.cpp", 0) MenuEntryIntEdit(ksGlobalTrickTextArray[i].c_str(), &GTrickList[i].Points, 0, 10000);
		AddEntry(pmeie);
	}
	c->Refresh();

	Menu::OnOpen(cto, c);

	mem_lock_malloc(memlocked);
}
